begin;create extension if not exists pgtap with schema extensions;select plan(15);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values('00000000-0000-0000-0000-000000000000','e0000000-0000-0000-0000-000000000001','authenticated','authenticated','m-a@example.test','',now(),'{}','{}',now(),now()),('00000000-0000-0000-0000-000000000000','e0000000-0000-0000-0000-000000000002','authenticated','authenticated','m-b@example.test','',now(),'{}','{}',now(),now());
insert into public.organizations(id,public_id,name)values('e1000000-0000-0000-0000-000000000001','org_marketingaaaaaaa','Marketing A'),('e1000000-0000-0000-0000-000000000002','org_marketingbbbbbbb','Marketing B');
insert into public.organization_memberships(id,organization_id,user_id,role,status)values('e2000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000001','owner','active'),('e2000000-0000-0000-0000-000000000002','e1000000-0000-0000-0000-000000000002','e0000000-0000-0000-0000-000000000002','owner','active');
insert into public.contacts(id,organization_id,created_by_membership_id,assigned_membership_id,first_name,last_name,primary_email,state_province,source,lifecycle_status,marketing_email_status)values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Ada','Eligible','ada@example.test','NC','Event','nurture','opted-in'),('e3000000-0000-0000-0000-000000000002','e1000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Sam','Suppressed','sam@example.test','SC','Event','prospect','suppressed'),('e3000000-0000-0000-0000-000000000003','e1000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Uma','Unknown','uma@example.test','VA','Referral','prospect','unknown');
set local role authenticated;select set_config('request.jwt.claim.sub','e0000000-0000-0000-0000-000000000001',true);
select ok(public.valid_segment_criteria('{"version":1,"combinator":"and","rules":[{"field":"state","operator":"isAnyOf","value":["NC","SC"]}]}'::jsonb),'criteria valid');
select ok(not public.valid_segment_criteria('{"version":1,"combinator":"and","rules":[{"field":"sql","operator":"is","value":"x"}]}'::jsonb),'arbitrary field denied');
insert into public.contact_tags(organization_id,created_by_membership_id,name)values('e1000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Semi-Absentee');insert into public.contact_tag_memberships select 'e1000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001',id,'e2000000-0000-0000-0000-000000000001',now() from public.contact_tags;
insert into public.contact_lists(organization_id,created_by_membership_id,name)values('e1000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Newsletter');insert into public.contact_list_memberships select 'e1000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001',id,'e2000000-0000-0000-0000-000000000001',now() from public.contact_lists;
select is((select max(total_count) from public.resolve_segment('{"version":1,"combinator":"and","rules":[{"field":"emailStatus","operator":"is","value":"opted-in"},{"field":"state","operator":"isAnyOf","value":["NC","SC"]}]}'::jsonb,25,0)),1::bigint,'AND criteria');
select is((select max(total_count) from public.resolve_segment('{"version":1,"combinator":"or","rules":[{"field":"state","operator":"is","value":"NC"},{"field":"state","operator":"is","value":"VA"}]}'::jsonb,25,0)),2::bigint,'OR criteria');
select is((select max(total_count) from public.resolve_segment(format('{"version":1,"combinator":"and","rules":[{"field":"tag","operator":"has","value":"%s"}]}',(select public_id from public.contact_tags))::jsonb,25,0)),1::bigint,'tag criteria');
select is((select max(total_count) from public.resolve_segment(format('{"version":1,"combinator":"and","rules":[{"field":"list","operator":"has","value":"%s"}]}',(select public_id from public.contact_lists))::jsonb,25,0)),1::bigint,'list criteria');
select is((select max(total_count) from public.resolve_segment('{"version":1,"combinator":"and","rules":[{"field":"candidate","operator":"is","value":"non-candidate"}]}'::jsonb,2,0)),3::bigint,'candidate relation criteria and bounded page');
insert into public.contact_segments(organization_id,created_by_membership_id,name,criteria)values('e1000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Email audience','{"version":1,"combinator":"and","rules":[{"field":"source","operator":"is","value":"Event"}]}');
select is((select max(matching_count) from public.resolve_campaign_audience('segment',(select public_id from public.contact_segments),25,0)),2::bigint,'campaign matching count');
select is((select max(eligible_count) from public.resolve_campaign_audience('segment',(select public_id from public.contact_segments),25,0)),1::bigint,'only opted-in eligible');
select is((select max(suppressed_count) from public.resolve_campaign_audience('segment',(select public_id from public.contact_segments),25,0)),1::bigint,'suppressed counted and excluded');
select is((select max(unknown_count) from public.resolve_campaign_audience('segment',(select public_id from public.contact_segments),25,0)),0::bigint,'unknown count accurate');
insert into public.marketing_campaigns(organization_id,created_by_membership_id,name,audience_type,audience_public_id)values('e1000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Launch','segment',(select public_id from public.contact_segments));
select is((select count(*) from public.marketing_campaigns),1::bigint,'campaign persisted');select is((select count(*) from public.contact_segments where organization_id='e1000000-0000-0000-0000-000000000002'),0::bigint,'other tenant hidden');
select throws_ok($$insert into public.contact_segments(organization_id,created_by_membership_id,name,criteria)values('e1000000-0000-0000-0000-000000000002','e2000000-0000-0000-0000-000000000002','Cross','{"version":1,"combinator":"and","rules":[{"field":"source","operator":"is","value":"x"}]}')$$,'42501',null,'cross organization denied');
select ok(not has_table_privilege('anon','public.marketing_campaigns','SELECT'),'anonymous campaign access denied');select * from finish();rollback;
